/**
 * Applying a chosen priority action: playing a land, casting a spell (with auto-payment),
 * moving the companion to hand. The option was generated by `computePriorityOptions`, so
 * legality holds; payment plans are recomputed here and must succeed.
 */

import type { ObjectId, PlayerId } from '@mtg/shared';
import type { Ability, AbilityCost, CardDefinition } from '../cards/definition';
import type { DecisionOutcome, GameGen } from '../decisions';
import { payAbilityCosts, payManaCost } from '../effects/resolve';
import { emit, debug } from '../log/log';
import type { ParsedManaCost } from '../mana/cost';
import { addGeneric, describeManaCost, emptyCost, subtractColored, subtractGeneric, totalPips, withX } from '../mana/cost';
import {
  makePermanent,
  moveObject,
  queueBecomesTargetedTriggers,
  queueCastTriggers,
  removeFromCurrentZone,
} from '../state/objects';
import { getDefByOracleId, wardCostOf } from '../state/queries';
import type {
  EngineCardObject,
  EnginePermanent,
  EnginePlayerState,
  EngineStackObject,
  GameContext,
} from '../state/types';
import type { PriorityActionPayload } from './legal';
import {
  computeTargetOptions,
  costReductionFor,
  manaPortionOf,
  pickCountSlotTargets,
  validateChosenTargets,
} from './legal';
import { resetOpponentYields } from '../turn/priority';

/**
 * The `Ability` a cast actually puts on the stack. A permanent card can print "this spell can't
 * be countered" with no `spellAbility` to carry the flag on (Dragonlord Dromoka) — give such a
 * cast a minimal zero-effect stack ability instead, purely so `protectedFromCounter` can see it.
 *
 * A modal spell's mode was chosen at announcement (CR 601.2b), as part of the option offered by
 * `computePriorityOptions` — substitute the chosen mode's `effects` for the ability's own here,
 * so the executor and every downstream consumer (fizzle check, description) never has to know
 * `modes` exists at all.
 */
function resolveCastAbility(
  def: CardDefinition,
  mode: number | undefined,
  cardName: string,
): Ability | null {
  if (def.spellAbility === null) {
    return def.spellCantBeCountered === true
      ? { kind: 'spell', targets: [], effects: [], cantBeCountered: true }
      : null;
  }
  const modes = def.spellAbility.modes;
  if (modes === undefined) return def.spellAbility;
  const chosen = modes.options[mode ?? 0];
  if (chosen === undefined) throw new Error(`engine bug: invalid mode ${mode} for ${cardName}`);
  return { ...def.spellAbility, effects: chosen.effects };
}

/**
 * Pay a whole activation cost. Non-mana components go first: they take the source out of play
 * (or tap it), so it cannot then also be tapped for mana to pay the same cost's mana half.
 * `computePriorityOptions` excludes the source for the same reason, so the two agree.
 */
function* payActivationCosts(
  ctx: GameContext,
  player: EnginePlayerState,
  perm: EnginePermanent,
  costs: readonly AbilityCost[],
): GameGen<void> {
  yield* payAbilityCosts(ctx, player, perm, costs, 'tap');
  const mana = manaPortionOf(costs);
  if (totalPips(mana) > 0) {
    // The purpose must match the one `computePriorityOptions` used to decide affordability, or
    // restricted mana that made the ability appear payable would not be spendable here.
    yield* payManaCost(ctx, player, mana, {
      kind: 'activateAbility',
      sourceOracleId: perm.oracleId,
    });
  }
}

/**
 * Ward (CR 702.21b): "whenever this becomes the target of a spell or ability an opponent
 * controls, counter it unless that player pays `<cost>`".
 *
 * Modeled as a *triggered ability*, not as a targeting restriction, and that is the load-bearing
 * decision. "Unless the controller pays" is a decision, and `isTargetStillLegal` — the function
 * a legality filter would have to live in — is a pure predicate that cannot ask a player
 * anything. As a trigger it also behaves correctly: it goes on the stack above the spell, so
 * the spell is still countered if ward resolves, and other responses can happen in between.
 */
function queueWardTriggers(
  ctx: GameContext,
  controllerId: PlayerId,
  stackObjectId: ObjectId,
  targets: readonly ObjectId[],
): void {
  for (const targetId of targets) {
    const perm = ctx.state.battlefield.find((p) => p.id === targetId);
    if (perm === undefined) continue;
    // "an opponent controls" — a permanent's own controller never triggers its ward.
    if (perm.controllerId === controllerId) continue;
    const cost = wardCostOf(ctx, perm);
    if (cost === null) continue;

    ctx.state.pendingTriggers.push({
      controllerId: perm.controllerId,
      sourceCardId: perm.cardId,
      sourceOracleId: perm.oracleId,
      sourceName: perm.name,
      ability: {
        kind: 'triggered',
        targets: [],
        effects: [{ op: 'counterUnlessPays', cost, stackObjectId }],
        description: `ward ${describeManaCost(cost)}`,
      },
    });
    debug(ctx, 'stack', `ward triggered: ${perm.name} (${describeManaCost(cost)})`);
  }
}

/**
 * Apply a non-pass priority action for `player`. Casting puts the spell on the stack
 * (targets chosen at announcement — brief §5.5); the caster retains priority (CR 117.3c).
 */
export function* applyPriorityAction(
  ctx: GameContext,
  player: EnginePlayerState,
  payload: PriorityActionPayload,
  outcome: DecisionOutcome,
): GameGen<void> {
  const s = ctx.state;
  switch (payload.kind) {
    case 'pass':
      throw new Error('engine bug: pass is not applied via applyPriorityAction');

    case 'playLand': {
      const obj = player.hand.find((o) => o.id === payload.objectId);
      if (obj === undefined) throw new Error('engine bug: land to play not in hand');
      player.landsPlayedThisTurn += 1;
      emit(ctx, 'playLand', { player: player.id, name: obj.name, cardId: obj.cardId }, player.id);
      debug(ctx, 'legalActions', `${player.id} plays ${obj.name}`);
      yield* moveObject(ctx, obj, { zone: 'battlefield', controllerId: player.id });
      return;
    }

    case 'castSpell': {
      const fromZone =
        payload.fromExile === true
          ? s.exile
          : payload.fromLibraryTop === true
            ? player.library
            : payload.fromCommand
              ? player.commandZone
              : player.hand;
      const obj = fromZone.find((o) => o.id === payload.objectId);
      if (obj === undefined) throw new Error('engine bug: spell to cast not found');
      const def = getDefByOracleId(ctx, obj.oracleId, obj.name);

      const tax = payload.fromCommand ? 2 * (player.commanderCastCount[obj.cardId] ?? 0) : 0;
      const reduction = costReductionFor(ctx, player.id, obj.oracleId, obj.cardId);
      const applyRed = (c: ParsedManaCost): ParsedManaCost => {
        let base = c;
        if (reduction.colored !== undefined) {
          base = subtractColored(base, reduction.colored);
        }
        return subtractGeneric(base, reduction.generic);
      };

      let cost: ParsedManaCost;
      let ability: Ability;
      let targets: ObjectId[];
      if (payload.alternativeCast === 'overload') {
        const alt = def.alternativeCasts?.find((a) => a.kind === 'overload');
        if (!alt) throw new Error('missing overload cost');
        cost = applyRed(alt.manaCost);
        ability = {
          kind: 'spell',
          targets: [],
          effects: [{ op: 'overloadBounceAllNonlandOpponents' }],
        };
        targets = [];
      } else if (payload.alternativeCast === 'adventure' || payload.alternativeCast === 'omen') {
        const alt =
          def.alternativeCasts?.[payload.altIndex ?? 0] ??
          def.alternativeCasts?.find((a) => a.kind === payload.alternativeCast);
        if (!alt) throw new Error(`missing ${payload.alternativeCast} cost`);
        cost = applyRed(alt.manaCost);
        ability = alt.ability ?? { kind: 'spell', targets: [], effects: [] };
        targets = validateChosenTargets(ctx, def, player.id, outcome.targets);
      } else {
        cost = withX(
          applyRed(addGeneric(def.manaCost ?? emptyCost(), tax)),
          payload.x ?? 0,
        );
        ability = resolveCastAbility(def, payload.mode, obj.name) ?? {
          kind: 'spell',
          targets: [],
          effects: [],
        };
        targets = validateChosenTargets(ctx, def, player.id, outcome.targets);
      }

      // CR 601.2b: every target, ordinary AND variable-count, is chosen as part of
      // announcement — before costs are paid. `validateChosenTargets` above already handled
      // the ordinary slots; a count slot ("up to one target creature", Primal Might) is picked
      // here the same way `pushTriggerOnStack` picks one for a triggered ability.
      const countTargets: Record<number, ObjectId[]> = {};
      for (const [i, spec] of ability.targets.entries()) {
        if (spec.count === undefined) continue;
        const alreadyChosen = new Set<ObjectId>([
          ...targets.filter((t): t is ObjectId => t !== undefined),
          ...Object.values(countTargets).flat(),
        ]);
        const picked = yield* pickCountSlotTargets(
          ctx,
          spec,
          player.id,
          obj.name,
          alreadyChosen,
          spec.count.max,
        );
        if (picked.length < spec.count.min) {
          throw new Error(`engine bug: could not meet minimum targets for slot ${i} of ${obj.name}`);
        }
        countTargets[i] = picked;
      }

      // "Becomes the target of a spell" (Thunderbreak Regent) fires at announcement (CR
      // 601.2c), before costs are paid.
      queueBecomesTargetedTriggers(ctx, player.id, [
        ...targets.filter((t): t is ObjectId => t !== undefined),
        ...Object.values(countTargets).flat(),
      ]);

      yield* payManaCost(ctx, player, cost, { kind: 'castSpell', oracleId: obj.oracleId });

      if (payload.fromCommand) {
        player.commanderCastCount[obj.cardId] = (player.commanderCastCount[obj.cardId] ?? 0) + 1;
      }

      resetOpponentYields(ctx, player.id);
      removeFromCurrentZone(ctx, obj);
      const spellCard: EngineCardObject = {
        ...obj,
        id: `o-${s.nextObjectNum++}` as ObjectId,
        zone: 'stack',
      };
      const spellEntry: EngineStackObject = {
        id: spellCard.id,
        sourceId: spellCard.id,
        controllerId: player.id,
        kind: 'spell',
        description: `${obj.name}`,
        targets,
        card: spellCard,
        ability,
        sourceOracleId: obj.oracleId,
        sourceCardId: obj.cardId,
        isCommanderCast: payload.fromCommand,
        ...(payload.alternativeCast ? { alternativeCastKind: payload.alternativeCast } : {}),
        ...(payload.x !== undefined ? { announcedX: payload.x } : {}),
        ...(Object.keys(countTargets).length > 0 ? { countTargets } : {}),
      };
      s.stack.push(spellEntry);
      emit(
        ctx,
        'castSpell',
        {
          player: player.id,
          name: obj.name,
          cardId: obj.cardId,
          targets,
          fromCommand: payload.fromCommand,
          commanderTax: tax,
        },
        player.id,
      );
      debug(ctx, 'stack', `${player.id} casts ${obj.name}${tax > 0 ? ` (tax {${tax}})` : ''}`, {
        targets,
      });
      // "Whenever you cast a Dragon spell" fires now, with the spell already on the stack below
      // it (CR 603.3b), so the trigger resolves first.
      queueCastTriggers(ctx, spellEntry);
      queueWardTriggers(ctx, player.id, spellCard.id, targets);
      return;
    }

    case 'activateAbility': {
      if (payload.fromGraveyard === true) {
        // CR 112.6a: the source is a graveyard card (Runehorn Hellkite), not a permanent — no
        // tap/summoning-sickness/`activationsThisTurn` bookkeeping applies, and paying the
        // `exileSelfFromGraveyard` cost removes it from the zone it is activating from, exactly
        // like a battlefield sacrifice cost removes a permanent (CR 601.2h: paying is one
        // indivisible act and happens even though the source is now gone).
        const card = player.graveyard.find((c) => c.id === payload.objectId);
        if (card === undefined) throw new Error('engine bug: ability source not in the graveyard');
        const def = getDefByOracleId(ctx, card.oracleId, card.name);
        const activated = def.activatedAbilities[payload.index];
        if (activated === undefined) throw new Error('engine bug: activated ability index invalid');

        const description = activated.ability.description ?? 'activated ability';
        const id = `o-${s.nextObjectNum++}` as ObjectId;
        const stackEntry = {
          id,
          sourceId: card.id,
          controllerId: player.id,
          kind: 'activatedAbility' as const,
          description: `${card.name} — ${description}`,
          targets: [],
          card: null,
          ability: activated.ability,
          sourceOracleId: card.oracleId,
          sourceCardId: card.cardId,
          isCommanderCast: false,
        };

        const mana = manaPortionOf(activated.costs);
        if (totalPips(mana) > 0) {
          yield* payManaCost(ctx, player, mana, {
            kind: 'activateAbility',
            sourceOracleId: card.oracleId,
          });
        }
        if (activated.costs.some((c) => c.kind === 'exileSelfFromGraveyard')) {
          yield* moveObject(ctx, card, { zone: 'exile' });
        }
        resetOpponentYields(ctx, player.id);
        s.stack.push(stackEntry);
        emit(
          ctx,
          'activateAbility',
          { player: player.id, source: card.name, cardId: card.cardId, description, targets: [] },
          player.id,
        );
        debug(ctx, 'stack', `${player.id} activates ${card.name} (graveyard) — ${description}`);
        return;
      }

      const perm = ctx.state.battlefield.find((p) => p.id === payload.objectId);
      if (perm === undefined) throw new Error('engine bug: ability source not on the battlefield');
      const def = getDefByOracleId(ctx, perm.oracleId, perm.name);
      const activated = def.activatedAbilities[payload.index];
      if (activated === undefined) throw new Error('engine bug: activated ability index invalid');

      // CR 601.2c/601.2h: targets are chosen, then costs are paid, then the ability is on the
      // stack. Paying is one indivisible act and happens even if the ability never resolves —
      // which is why sacrificing the source does not remove the ability from the stack.
      const targets: ObjectId[] = [];
      for (const [slot, spec] of activated.ability.targets.entries()) {
        const choice = outcome.targets.get(slot);
        if (choice === undefined) throw new Error(`missing target for slot ${slot} of ${perm.name}`);
        if (!computeTargetOptions(ctx, spec, player.id).includes(choice)) {
          throw new Error(`illegal target ${choice} for slot ${slot} of ${perm.name}`);
        }
        targets.push(choice);
      }
      queueBecomesTargetedTriggers(ctx, player.id, targets);

      const description = activated.ability.description ?? 'activated ability';
      const id = `o-${s.nextObjectNum++}` as ObjectId;
      // Snapshot before paying: a sacrifice cost removes the permanent, and the stack entry
      // must still name its source (CR 608.2f — the ability resolves regardless).
      const stackEntry = {
        id,
        sourceId: perm.id,
        controllerId: player.id,
        kind: 'activatedAbility' as const,
        description: `${perm.name} — ${description}`,
        targets,
        card: null,
        ability: activated.ability,
        sourceOracleId: perm.oracleId,
        sourceCardId: perm.cardId,
        isCommanderCast: false,
        ...(payload.x !== undefined ? { announcedX: payload.x } : {}),
      };

      // {X} was announced as part of activating (CR 602.1b) — fold it into the mana
      // component's generic amount before paying, the same way `withX` does for {X} spells.
      const costsToPay =
        payload.x === undefined
          ? activated.costs
          : activated.costs.map((c) =>
              c.kind === 'mana' ? { kind: 'mana' as const, cost: withX(c.cost, payload.x as number) } : c,
            );
      yield* payActivationCosts(ctx, player, perm, costsToPay);
      // Recorded at ANNOUNCEMENT (CR 602.5f), not on resolution: the restriction is on
      // activating, so countering the ability does not give the activation back.
      if (activated.oncePerTurn === true) perm.activationsThisTurn.push(payload.index);
      resetOpponentYields(ctx, player.id);
      s.stack.push(stackEntry);
      emit(
        ctx,
        'activateAbility',
        { player: player.id, source: perm.name, cardId: perm.cardId, description, targets },
        player.id,
      );
      debug(ctx, 'stack', `${player.id} activates ${perm.name} — ${description}`);
      queueWardTriggers(ctx, player.id, id, targets);
      return;
    }

    case 'companionToHand': {
      const companion = player.companion;
      if (companion === null || player.companionMovedToHand) {
        throw new Error('engine bug: companion action without a companion');
      }
      yield* payManaCost(ctx, player, { ...emptyCost(), generic: 3 });
      player.companionMovedToHand = true;
      const handObj: EngineCardObject = {
        ...companion,
        id: `o-${s.nextObjectNum++}` as ObjectId,
        zone: 'hand',
      };
      player.hand.push(handObj);
      player.companion = null;
      emit(ctx, 'companionToHand', { player: player.id, name: companion.name }, player.id);
      return;
    }
  }
}

export { makePermanent };
